# Test data again - I'll create a proper version

def transform(grid):
    h = len(grid)
    w = len(grid[0])

    from collections import Counter
    counts = Counter()
    for row in grid:
        for x in row:
            counts[x] += 1
    background = counts.most_common(1)[0][0]

    non_bg = [c for c in counts if c != background]
    if not non_bg:
        return grid

    main_color = non_bg[0]
    new_color = 4

    horizontal_segments = []
    vertical_segments = []

    for r in range(h):
        row_vals = grid[r]
        non_bg_cols = [c for c in range(w) if row_vals[c] == main_color]
        if non_bg_cols:
            i = 0
            while i < len(non_bg_cols):
                start = non_bg_cols[i]
                end = start
                while end + 1 < len(non_bg_cols) and non_bg_cols[end+1] == non_bg_cols[end] + 1:
                    end += 1
                if end - start >= 0:
                    horizontal_segments.append((r, start, end))
                i = end + 1

    for c in range(w):
        col_vals = [grid[r][c] for r in range(h)]
        non_bg_rows = [r for r in range(h) if col_vals[r] == main_color]
        if non_bg_rows:
            i = 0
            while i < len(non_bg_rows):
                start = non_bg_rows[i]
                end = start
                while end + 1 < len(non_bg_rows) and non_bg_rows[end+1] == non_bg_rows[end] + 1:
                    end += 1
                if end - start >= 0:
                    vertical_segments.append((c, start, end))
                i = end + 1

    result = [list(row) for row in grid]

    for hr, hstart, hend in horizontal_segments:
        for c in range(hstart, hend + 1):
            for vc, vstart, vend in vertical_segments:
                if vc == c and vstart <= hr <= vend and grid[hr][c] == background:
                    result[hr][c] = new_color

    for vc, vstart, vend in vertical_segments:
        for r in range(vstart, vend + 1):
            for hr, hstart, hend in horizontal_segments:
                if hr == r and hstart <= vc <= hend and grid[r][vc] == background:
                    result[r][vc] = new_color

    return result

