def transform_v9(grid):
    from collections import Counter
    h = len(grid)
    w = len(grid[0])
    counts = Counter()
    for row in grid:
        for x in row:
            counts[x] += 1

    background = counts.most_common(1)[0][0]
    non_bg = [c for c in counts if c != background]
    if not non_bg:
        return grid

    main_color = non_bg[0]

    crossing_rows = set()
    crossing_col_ranges = {}
    for r in range(h):
        non_bg_cols = sorted([c for c in range(w) if grid[r][c] == main_color])
        i = 0
        while i < len(non_bg_cols):
            start = non_bg_cols[i]
            end = start
            while end + 1 < len(non_bg_cols) and non_bg_cols[end+1] == non_bg_cols[end] + 1:
                end += 1
            if end - start >= 2:
                crossing_rows.add(r)
                if r not in crossing_col_ranges:
                    crossing_col_ranges[r] = []
                crossing_col_ranges[r].append((start, end, (start+end)//2))
            i = end + 1

    print(f"Crossing rows: {sorted(crossing_rows)}")
    print(f"Col ranges: {crossing_col_ranges}")

    # Don't filter by crossing_col_ranges[r][0][2] == c - just check coverage
    # Actually let's store each "aligned" column separately, not just the middle

    # New idea: For each crossing row, extract all columns in its segments
    # Group columns by which crossing rows contain them
    col_to_rows = {}  # col -> list of crossing row indices (where col appears in the segment)

    for r in sorted(crossing_rows):
        for start, end, _ in crossing_col_ranges[r]:
            if start not in col_to_rows:
                col_to_rows[start] = []
            if end not in col_to_rows:
                col_to_rows[end] = []
            if (start+end)//2 not in col_to_rows or crossing_col_ranges[r] == [(start, end, (start+end)//2)]:
                pass  # might already exist, let me redo this

    # Actually, let me just record all unique columns that appear in any segment
    all_cols = set()
    for r in crossing_rows:
        for start, end, mid in crossing_col_ranges[r]:
            for c in range(start, end + 1):
                all_cols.add(c)
                if c not in col_to_rows:
                    col_to_rows[c] = []
            col_to_rows[mid].append(r)
        for start, end, _ in crossing_col_ranges[r]:
            if start not in col_to_rows:
                col_to_rows[start] = []
            col_to_rows[start].append(r)
            if end not in col_to_rows:
                col_to_rows[end] = []
            col_to_rows[end].append(r)

    print(f"All cols: {sorted(all_cols)}")
    print(f"Col to crossing rows:")
    for c in sorted(col_to_rows):
        print(f"  Col {c}: {col_to_rows[c]}")

    # Simpler approach: use bounds checking instead of "aligned" columns
    return col_to_rows

col_to_rows = transform_v9(input_demo1)
print(f"\nCol to crossing rows: {col_to_rows}")

